 onMount(()=>{
  let disposed=false,disposeMotion:(()=>void)|undefined;
  const start=()=>{if(!disposed)disposeMotion=(window as any).__starliHomepageMotionV1?.start(homepageRoot);};
  let loader=document.querySelector<HTMLScriptElement>('script[data-starli-homepage-motion-loader]');
  if((window as any).__starliHomepageMotionV1?.start)start();
  else{
   if(!loader){
    loader=document.createElement('script');
    loader.src='/starli-art/homepage-motion-v1.js';
    loader.dataset.starliHomepageMotionLoader='v1';
    loader.async=true;
    loader.addEventListener('load',start,{once:true});
    document.head.appendChild(loader);
   }else loader.addEventListener('load',start,{once:true});
  }
  return ()=>{disposed=true;loader?.removeEventListener('load',start);disposeMotion?.();};
 });

